CREATE TABLE `payments` (
  `payment_id` varchar(12) NOT NULL,
  `merchant_id` varchar(255) NOT NULL,
  `button_id` varchar(12) NOT NULL,
  `transaction_id` varchar(64) NOT NULL,
  `amount` bigint unsigned NOT NULL,
  `payer_id` varchar(255) DEFAULT NULL,
  `txid` varchar(64) DEFAULT NULL,
  `completed` tinyint(1) NOT NULL DEFAULT '0',
  `is_new` tinyint(1) NOT NULL DEFAULT '1',
  `blockchain_transaction` longtext,
  `exchange_rate` decimal(24,10) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `description` text,
  PRIMARY KEY (`payment_id`),
  KEY `payments_merchant_id_foreign` (`merchant_id`),
  KEY `payments_button_id_foreign` (`button_id`),
  CONSTRAINT `payments_button_id_foreign` FOREIGN KEY (`button_id`) REFERENCES `ids` (`id`) ON DELETE CASCADE,
  CONSTRAINT `payments_merchant_id_foreign` FOREIGN KEY (`merchant_id`) REFERENCES `merchants` (`merchant_id`) ON DELETE CASCADE,
  CONSTRAINT `payments_payment_id_foreign` FOREIGN KEY (`payment_id`) REFERENCES `ids` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
